INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(2521, 'koKR', 'Na usługach Kum\'ishy', '$R, czy twój malutki mózg jest w stanie pojąć, jak rzadka jest nieskazitelna kula draenetystu? Draenei spędzali całe życie na poszukiwaniu choćby jednego z tych kryształów, by w końcu spotkał ich straszny los, a ich cel pozostał niespełniony.$B$BA więc stoisz przed Kum\'ishą, wiesz, o co Kum\'isha prosi, i nadal chcesz pomóc? Dobrze więc, $r... Jeśli kiedykolwiek podczas wędrówek po tych ziemiach znajdziesz nieskazitelną kulę draenetystu, przynieś mi ją, a nagrodzę cię bogactwem przekraczającym twoje najśmielsze marzenia.', 'Jeśli podczas wędrówek po Jałowych Ziemiach kiedykolwiek natrafisz na nieskazitelną kulę draenetystu, zanieś ją Kum\'ishy Kolekcjonerowi.$B$BUwaga: ten klejnot to jeden z najrzadszych kryształów w całym Azeroth. Nieskazitelną kulę draenetystu może mieć przy sobie każde stworzenie w tej krainie.$B$BZa każdą zebraną nieskazitelną kulę draenetystu otrzymasz nagrodę.', '', 'Wróć do Kum\'ishy Kolekcjonera na Jałowych Ziemiach.', '', '', '', '', 0),
(2522, 'koKR', 'Starania Kum\'ishy', 'Choć przywołanie portalu się nie powiodło, wciąż mam nadzieję, że następna próba zakończy się sukcesem.$B$BNadzieja draenei jest równie żarliwa jak twoja chciwość na błyskotki, $r. Wracaj na te przeklęte ziemie i zdobądź kolejną nieskazitelną kulę draenetystu.$B$BOczywiście to, czy podejmiesz się tego zadania, zależy wyłącznie od ciebie *uśmiech*.', 'Znajdź nieskazitelną kulę draenetystu i przynieś ją Kum\'ishy Kolekcjonerowi.', '', 'Wróć do Kum\'ishy Kolekcjonera na Jałowych Ziemiach.', '', '', '', '', 0),
(2581, 'koKR', 'Podgardla chichokłów', 'Powszechnie wiadomo, że hieny mają ogromną siłę w szczękach, ale żeby przegryźć trzy cale stali z torium? Niemożliwe, nieprawdopodobne, a jednak widziałem to na własne oczy.$B$BWyrusz na Jałowe Ziemie i przynieś mi trzy podgardla chichokłów. Szukając chichokłów, wypatruj też dzików i skorpoków: do pierwszej próbki potrzebuję jeszcze dwóch płuc dzika z Jałowych Ziem i jednych szczypiec skorpoka.', 'Przynieś trzy podgardla chichokłów, dwa płuca dzika z Jałowych Ziem i jedne szczypce skorpoka magowi krwi Drazialowi.', '', 'Wróć do maga krwi Draziala na Jałowych Ziemiach.', '', '', '', '', 0),
(2582, 'koKR', 'Wściekłość wieków', 'Ach, $N, witaj z powrotem. Widzę, że spodobało ci się działanie Rewelacyjnej Odżywki Ino Dla Siłaczy z chichokła. Ostrzegam jednak: choć natychmiastowym skutkiem jest tytaniczny przypływ siły, długofalowy wpływ na twojego ducha i intelekt może być groźny.$B$BA skoro już o tym mowa – chcesz więcej? Jeśli tak, przynieś mi kolejne trzy podgardla chichokłów, dwa płuca dzika z Jałowych Ziem i jedne szczypce skorpoka.', 'Przynieś trzy podgardla chichokłów, dwa płuca dzika z Jałowych Ziem i jedne szczypce skorpoka magowi krwi Drazialowi.', '', 'Wróć do maga krwi Draziala na Jałowych Ziemiach.', '', '', '', '', 0),
(2583, 'koKR', 'Witalność dzika', 'Na tych jałowych ziemiach żyją dwa gatunki dzików: popielatogrzywy dzik i piekielny dzik.$B$BWygląda na to, że wytrzymałość czyni te bestie niemal niewrażliwymi na zranienia – inne zwierzęta uważają, że zbyt trudno je zabić, a zatem nie są warte zachodu.$B$BMusimy przeprowadzić dalsze badania, $N. Jeśli przyniesiesz mi trzy płuca dzika z Jałowych Ziem, dwoje szczypiec skorpoka i jeden mózg bazyliszka, z pozostałości po preparacie stworzę boski eliksir. Będziesz moim pierwszym obiektem badań!', 'Przynieś trzy płuca dzika z Jałowych Ziem, dwoje szczypiec skorpoka i jeden mózg bazyliszka magowi krwi Drazialowi.$B', '', 'Wróć do maga krwi Draziala na Jałowych Ziemiach.', '', '', '', '', 0),
(2584, 'koKR', 'Duch dzika', 'Gdy po raz pierwszy podałem ci eliksir, $N, wiedziałem, że jedna czy dwie dawki nie zaspokoją twojego apetytu. Nawet teraz widzę głód w twoich oczach. Ta mikstura uzależnia, a jak widać, nie potrafią się jej oprzeć nawet ludzie o najsilniejszej woli.$B$BNiech tak będzie! Jeśli potrzebujesz więcej koktajlu z soku płucnego, wracaj na pustkowia i znajdź mi trzy płuca dzika z Jałowych Ziem, dwoje szczypiec skorpoka i jeden mózg bazyliszka.', 'Przynieś trzy płuca dzika z Jałowych Ziem, dwoje szczypiec skorpoka i jeden mózg bazyliszka magowi krwi Drazialowi.$B', '', 'Wróć do maga krwi Draziala na Jałowych Ziemiach.', '', '', '', '', 0),
(2585, 'koKR', 'Zdecydowany cios', '$GWidziałeś:Widziałaś; je kiedyś w walce, $N? Skorpoki, znaczy się. $GWidziałeś:Widziałaś;, z jaką gracją i zwinnością się poruszają? Jak zdecydowane są ich ciosy?$B$BGdybyśmy tylko zdołali jakoś wyodrębnić tę zwinność i zamknąć ją w kapsułce, bylibyśmy bogaci ponad... to znaczy... byłoby to dobrodziejstwo dla społeczności naukowej.$B$BPomóż mi, $N, a pozwolę ci skosztować preparatu.$B$BAby stworzyć stabilną próbkę, potrzebuję trojga szczypiec skorpoka, dwóch żołądków sępa i jednego płuca dzika z Jałowych Ziem.', 'Przynieś troje szczypiec skorpoka, dwa żołądki sępa i jedno płuco dzika z Jałowych Ziem magowi krwi Drazialowi.$B', '', 'Wróć do maga krwi Draziala na Jałowych Ziemiach.', '', '', '', '', 0),
(2586, 'koKR', 'Sól skorpoka', 'Żyjesz! To doprawdy dobra wiadomość. Zakładam, że $gwróciłeś:wróciłaś; po więcej preparatu ze skorpoka?$B$BDobrze więc, $N, wracaj na pustkowia i nie pokazuj się, dopóki nie zbierzesz trojga szczypiec skorpoka, dwóch żołądków sępa i jednego płuca dzika z Jałowych Ziem.', 'Przynieś troje szczypiec skorpoka, dwa żołądki sępa i jedno płuco dzika z Jałowych Ziem magowi krwi Drazialowi.', '', 'Wróć do maga krwi Draziala na Jałowych Ziemiach.', '', '', '', '', 0),
(2601, 'koKR', 'Ukąszenie bazyliszka', 'Te pustkowia roją się od czerwonokamiennych bazyliszków, $N. Przystosowały się i rozpleniły się tu bardziej niż jakiekolwiek inne zwierzęta w tym regionie.$B$BObserwowałam z daleka, jak polują i jak wygląda ich codzienność – te bestie wykazują procesy myślowe bardziej złożone niż niektóre istoty humanoidalne.$B$BMuszę zbadać ich mózgi!$B$BZdobądź dla mnie dziesięć ich mózgów, $N. Mieszanka nie będzie jednak kompletna bez dwóch żołądków sępa, które stanowią bazę roztworu.', 'Przynieś dziesięć mózgów bazyliszka i dwa żołądki sępa magini krwi Lynnore.$B', '', 'Wróć do magini krwi Lynnore na Jałowych Ziemiach.', '', '', '', '', 0),
(2602, 'koKR', 'Nieomylny umysł', 'Twoje skupienie tak szybko osłabło? Trzeba przeprowadzić więcej badań!$B$BO tak, cena pozostaje ta sama, $N. Wyrusz na jałowe ziemie i wróć do mnie z dziesięcioma mózgami czerwonokamiennych bazyliszków i dwoma żołądkami sępa.$B', 'Przynieś dziesięć mózgów bazyliszka i dwa żołądki sępa magini krwi Lynnore.', '', 'Wróć do magini krwi Lynnore na Jałowych Ziemiach.', '', '', '', '', 0),
(2603, 'koKR', 'Wigor sępa', 'Śmierć na tych jałowych ziemiach naprawdę ma skrzydła, $r. Widziałam, jak czarni pogromcy i kościskuby ucztują na zwłokach niejednego poległego odkrywcy – czasem żywiąc się najbardziej plugawą i zarażoną padliną. Aż dziw, jak ich organizmy radzą sobie z zarazą, która trawi te ziemie.$B$BPomóż mi w badaniach, $N! Potrzebuję żołądków! Do bazy mikstury potrzebne będą też dwa podgardla chichokłów.$B$BZa swoje wysiłki zostaniesz podwójnie $gnagrodzony:nagrodzona;.', 'Przynieś dziesięć żołądków sępa i dwa podgardla chichokłów magini krwi Lynnore.$B', '', 'Wróć do magini krwi Lynnore na Jałowych Ziemiach.', '', '', '', '', 0),
(2604, 'koKR', 'Duchowa dominacja', 'Widzę, że wewnętrzny ogień przygasł. Czy duchowa euforia trwała godzinę?$B$BJeśli pragniesz więcej gumy z żołądka, to ja potrzebuję więcej żołądków. Wracaj na pustkowia, $N. Nie pokazuj się, dopóki nie zdobędziesz dziesięciu żołądków i dwóch podgardli.', 'Przynieś dziesięć żołądków sępa i dwa podgardla chichokłów magini krwi Lynnore.$B', '', 'Wróć do magini krwi Lynnore na Jałowych Ziemiach.', '', '', '', '', 0),
(3501, 'koKR', 'Liczy się ilość', 'Choć być może nigdy nie znajdziesz nieskazitelnej kuli draenetystu, podczas wędrówek po tych ziemiach z pewnością natrafisz na różne niedoskonałe fragmenty draenetystu.$B$BWątpliwe, by Kum\'isha zdołał wykorzystać wadliwe fragmenty do powrotu do domu, ale mogą one posłużyć draenei do innych, pożytecznych celów.$B$BPrzynieś mi każdy fragment wadliwego draenetystu, jaki znajdziesz, a nagrodzę cię.', 'Przynieś Kum\'ishy niedoskonałe fragmenty draenetystu i odbierz nagrodę za każdy oddany fragment.$B', '', 'Wróć do Kum\'ishy Kolekcjonera na Jałowych Ziemiach.', '', '', '', '', 0),
(3502, 'koKR', 'Co dla draenei rupieć...', 'Po takim pokazie nienasyconej chciwości zbiera mi się na mdłości.$B$BTak czy inaczej, nie będę się zbyt długo rozwodził nad twoim uzależnieniem od dóbr materialnych.$B$BZa każdy oddany niedoskonały fragment draenetystu nagrodzę cię kolejnymi rupieciami. Moja sterta rupieci maleje, a twoja rośnie. Na Draenorze nazywamy to sytuacją, w której obie strony wygrywają.$B', 'Przynieś Kum\'ishy niedoskonałe fragmenty draenetystu. Fragment może mieć przy sobie każdy potwór na Jałowych Ziemiach.$B', '', 'Wróć do Kum\'ishy Kolekcjonera na Jałowych Ziemiach.', '', '', '', '', 0),
(7581, 'koKR', 'Spoiwo więzienia', 'Musisz zdobyć od pomniejszych demonów spoiwo do więzienia strażnika Zagłady.$B$BKrew satyrów z Dzikiego Pomiotu, które zajmują Srogomłot, doskonale się nada. Zakrzepła krew zwiąże odłamki Hederine i zasili kryształowe więzienie.', 'Udaj się do Srogomłotu w Feralas i zdobądź 15 fiolek krwi satyra od satyrów z Dzikiego Pomiotu, które zamieszkują Dzielnicę Wypaczonego Drzewa. Gdy to zrobisz, wróć do Daia na Skażonej Bliźnie.$B', '', 'Wróć do Daia Zgrzybiałego na Jałowych Ziemiach.', '', '', '', '', 0),
(7582, 'koKR', 'Obudowa więzienia', 'Demony Hederine, które zajmują podnóże Góry Hyjal, wydzielają potężne trucizny spaczenia. Pozostawione do dojrzenia twardnieją w gęsty kryształ tłumiący magię. Kryształy te zwie się Łzami Hederine.$B$BNawet ogromna moc strażnika Zagłady nie zdołałaby skruszyć ścian więzienia zbudowanego z tego materiału.$B$BUdaj się do Wąwozu Mrocznego Szeptu w Zimozdroju i zdobądź Łzy.', 'Udaj się do Wąwozu Mrocznego Szeptu w Zimozdroju i zdobądź 5 Łez Hederine od demonów Hederine, które zajmują wąwóz. Gdy wykonasz to zadanie, wróć do Daia na Skażonej Bliźnie.', '', 'Wróć do Daia Zgrzybiałego na Jałowych Ziemiach.', '', '', '', '', 0),
(7583, 'koKR', 'Stłumienie', 'Więzienie jest gotowe. Teraz najtrudniejsza część zadania.$B$BMusisz odnaleźć na Skażonej Bliźnie dowódcę strażników Zagłady i schwytać go za pomocą tego kryształowego więzienia.$B$BStrzeż się! Strażnik Zagłady to przebiegły i zabójczy przeciwnik – gdy rozpoczniesz rytuał uwięzienia, będzie próbował cię zniszczyć. W próbach ucieczki będzie szaleńczo miotał się na wszystkie strony.$B$BSkupi się wyłącznie na tobie, $N. Dlatego radzę ci zabrać towarzyszy, którzy zdołają utrzymać cię przy życiu!', 'Wyrusz na Skażoną Bliznę i odszukaj dowódcę strażników Zagłady.$B$BUżyj na nim Lśniącego kryształowego więzienia. Przygotuj się na zaciekły grad ciosów, gdy demon będzie próbował uniknąć schwytania.$B$BJeśli ci się uda, zanieś Uwięzionego strażnika Zagłady Daiowi na Skażonej Bliźnie.', '', 'Wróć do Daia Zgrzybiałego na Jałowych Ziemiach.', '', '', '', '', 0),
(9407, 'koKR', 'Przez Mroczny Portal', 'Przez lata Mroczny Portal górował w ciszy... zapomniany. Ale już nie milczy.$B$BPowstrzymawszy tu atak demonów, nasze siły przedarły się przez portal i starły się z demonami na ich własnym terenie!$B$BTeraz tkwimy w zażartej wojnie i są tacy, którzy sądzą, że możemy jej nie wygrać. Dlatego naszym obowiązkiem, naszą ponurą przyjemnością, jest walczyć z pomiotem Rubieży i zapewnić nam zwycięstwo, $N.$B$BJeśli chcesz nam pomóc, natychmiast zgłoś się do generała porucznika Oriona. Czeka na ciebie w Rubieży...$B', 'Przejdź przez Mroczny Portal i odnajdź generała porucznika Oriona. Czeka na ciebie po drugiej stronie, w Rubieży.$B', '', '', '', '', '', '', 0),
(10119, 'koKR', 'Przez Mroczny Portal', 'Przez 20 lat Mroczny Portal pozostawał milczącym pomnikiem – mową pogrzebową dla dawno zapomnianych czasów.$B$B<Relthorn rozgląda się wokół.>$B$BNie sądziłem, że doczekam tego dnia, a jednak oto stoimy i spoglądamy w otchłań.$B$BPo drugiej stronie tej bramy toczymy zażartą wojnę – wojnę, której nie wygramy bez wsparcia. Musisz przejść przez Mroczny Portal i pomóc naszym oddziałom, $N.$B$BNatychmiast zgłoś się do dowódcy Durona. Czeka na ciebie w Rubieży...', 'Przejdź przez Mroczny Portal i odnajdź dowódcę Durona. Czeka na ciebie po drugiej stronie – w Rubieży.$B', '', '', '', '', '', '', 0),
(10259, 'koKR', 'W wyłom', 'Przy portalu bitwa trwa bez przerwy! Argentowy Brzask toczy rozpaczliwą walkę – a jeśli przegramy, ogień demonów nigdy nie zgaśnie.$B$BPomóż nam, $N. Wkrocz w wyłom i wesprzyj naszych braci i siostry. Pomóż powstrzymać tę falę ciemności! Argentowy Brzask – i cały świat – cię potrzebuje!', 'Zabij 6 strażników Spaczenia-najeźdźców, a następnie wróć do emisariusza Argentowego Brzasku Proudwella.', '', 'Wróć do agenta Proudwella przy Mrocznym Portalu na Jałowych Ziemiach.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(2521, 'koKR', 'Czy wzrok mnie myli? Niemożliwe! Gdzie ty... Jak...$B$BByć może teraz uda się otworzyć szczelinę, przez którą wrócimy do ojczyzny.', 0),
(2522, 'koKR', 'Po prostu zdumiewające. Wątpiłem, czy zdołasz znaleźć kolejną kulę, a jednak oto pulsuje w moich dłoniach.$B$BDobra robota, $N!$B$BJeśli znajdziesz ich więcej – choć uważam to za niemożliwe – przynieś mi je, a znów cię nagrodzę.', 0),
(2581, 'koKR', 'Jak się czujesz, $N? Promieniujesz aurą chichokła – twoja siła nie ma sobie równych wśród śmiertelników!$b$bNiestety z przyniesionych składników zdołałem przygotować preparat tylko na jedną tabletkę. Jeśli będziesz potrzebować kolejnej, będę potrzebował więcej składników.', 0),
(2582, 'koKR', 'Proszę bardzo! Pamiętaj, używaj oszczędnie. Jeśli będziesz potrzebować kolejnej, przyjdź do mnie, gdy zużyjesz tę, którą masz teraz.', 0),
(2583, 'koKR', 'Duch dzika rozświetla twoją istotę, $N! Ciekawe, czy uważasz się teraz za równie niewrażliwego na ciosy jak te bestie?', 0),
(2584, 'koKR', 'Muszę cię ostrzec, $N: nie próbuj łączyć stworzonych przeze mnie formuł. Właściwości chemiczne formuły, którą $gprzyjąłeś:przyjęłaś; ostatnio, zawsze biorą górę nad wcześniejszymi zaklęciami, przez co tamta formuła przestaje działać.', 0),
(2585, 'koKR', 'Fascynujące. To był najtrudniejszy do zbadania ze wszystkich preparatów.$b$bWeź szczyptę tej pozostałej soli i włóż ją pod język. Powinno ogarnąć cię lekkie uczucie euforii, a po nim bezprecedensowa zwinność i szybkość.', 0),
(2586, 'koKR', 'Świetna robota, $N. Oto jedna próbka preparatu dla ciebie, a pozostałe dziewięć posłuży moim badaniom.$b$bJeśli kiedykolwiek będziesz potrzebować więcej próbki mielonego skorpoka, wróć do mnie, a dobijemy targu.', 0),
(2601, 'koKR', 'To cudowne, $N! W podzięce daję ci posmakować wewnętrznych mechanizmów czerwonokamiennego bazyliszka.$B$BJeśli mieszanka przypadnie ci do gustu, zawsze można zrobić więcej... za odpowiednią cenę.', 0),
(2602, 'koKR', 'Tak, tak, daj mi chwilę, a przygotuję więcej mieszanki do spożycia, $N.$B$BWeź ją... i $N, nie próbuj przyjmować tych eksperymentalnych mikstur jedna po drugiej. Skutki mogłyby być katastrofalne.', 0),
(2603, 'koKR', 'Wyśmienicie! Natychmiast biorę się do pracy. Może znajdzie się lekarstwo na wiele bolączek tego świata!$B$BAch tak, twoja nagroda – oczywiście, jeśli będziesz potrzebować więcej gumy, wróć do mnie, a dostaniesz kolejne zadanie.', 0),
(2604, 'koKR', 'Być może pewnego dnia zdołam wyodrębnić aktywne enzymy z tego preparatu i uzyskać znacznie skuteczniejszy produkt. Niestety na razie musisz się zadowolić tym, co jestem w stanie wytworzyć. Wróć do mnie, jeśli będziesz potrzebować więcej gumy z żołądka.', 0),
(3501, 'koKR', 'Naprawdę mnie brzydzisz, $r. $GDorosły mężczyzna:Dorosła kobieta; śliniący się nad stertą rupieci? Żałosne! Bierz swoją nagrodę i zejdź mi z oczu.', 0),
(3502, 'koKR', 'Naprawdę mnie brzydzisz, $r. $GDorosły mężczyzna:Dorosła kobieta; śliniący się nad stertą rupieci? Żałosne! Bierz swoją nagrodę i zejdź mi z oczu.$B$BZnajome? Powinno być, bo mówię to tysiąc razy dziennie.$B$BOch, jak ja nienawidzę tego świata.', 0),
(7581, 'koKR', 'Ach, doskonała zdobycz. Ta krew stłumi magiczną obronę strażnika Zagłady.', 0),
(7582, 'koKR', 'Muszę tylko połączyć krew satyrów z Dzikiego Pomiotu z tymi kryształami, a więzienie będzie gotowe do użycia.', 0),
(7583, 'koKR', '$GZrobiłeś:Zrobiłaś;, o co prosiłem. Jesteś $ggotów:gotowa; przyjąć wiedzę, jak przyzywać tę bestię i nad nią panować.', 0),
(9407, 'koKR', 'Nasza ekspedycja bezpiecznie przeszła przez Portal i założyła nową bazę o nazwie Thrallmar. Jednak jak widzisz, Płonący Legion wkroczył i odciął nas od naszych braci. Demony najwyraźniej chcą odbić Mroczny Portal i nie dopuścić, byśmy ściągali posiłki z Azeroth.', 0),
(10119, 'koKR', 'Witaj w Rubieży, $N – witaj w koszmarze! Choć pierwsze siły ekspedycyjne przeszły bez szwanku, Legion próbuje odbić Mroczny Portal i nie dopuścić do przejścia naszych posiłków.$B$BChoć chętnie przyjąłbym tu twoją pomoc, nasze oddziały wraz z żołnierzami Hordy są w stanie odpierać plutony Legionu, które próbują przejąć kontrolę nad tą platformą.$B$BPotrzebujemy cię tam, gdzie twoje talenty najlepiej się przydadzą.', 0),
(10259, 'koKR', 'Dziękuję, $N. Pośród chaosu bitwy bohaterowie płoną jasno w ciemności. Twoje światło świeci prawdziwym blaskiem!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(2521, 'koKR', 'Poświęciłem życie poszukiwaniu nieskazitelnych kul draenetystu. Całe życie, $r!', 0),
(2522, 'koKR', '$GZnalazłeś:Znalazłaś; kolejną nieskazitelną kulę draenetystu?', 0),
(2581, 'koKR', 'Cuchniesz, $N. $GŁaziłeś:Łaziłaś; po polach siarki? I gdzie są moje składniki?!', 0),
(2582, 'koKR', 'Masz organy zwierząt?', 0),
(2583, 'koKR', 'Gdzie są organy, $N!?', 0),
(2584, 'koKR', 'Gdzie są organy, $N!?', 0),
(2585, 'koKR', 'Gdzie są organy, $N!?', 0),
(2586, 'koKR', 'Gdzie są organy, $N!?', 0),
(2601, 'koKR', '$GWróciłeś:Wróciłaś; z organami, o które prosiłam?', 0),
(2602, 'koKR', '$GWróciłeś:Wróciłaś; z organami, o które prosiłam?', 0),
(2603, 'koKR', 'Nie marnuj mojego czasu, $N. Nie mamy o czym rozmawiać, chyba że $gzdobyłeś:zdobyłaś; to, o co prosiłam.', 0),
(2604, 'koKR', 'Nie marnuj mojego czasu, $N. Nie mamy o czym rozmawiać, chyba że $gzdobyłeś:zdobyłaś; to, o co prosiłam.', 0),
(3501, 'koKR', 'Czy w swoich wędrówkach $gmiałeś:miałaś; szczęście?', 0),
(3502, 'koKR', 'No i? Draenetyst? Pamiętasz?$B$B<Kum\'isha zaciska pięść i puka cię w głowę.>$B$BJest tam kto?', 0),
(7581, 'koKR', 'Wystarczy tylko krew satyrów z Dzikiego Pomiotu.', 0),
(7582, 'koKR', 'Hederine nie oddadzą swoich cennych klejnotów bez walki, $N.', 0),
(7583, 'koKR', 'Hm? No i?', 0);
