INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3441, 'koKR', '%s wypuszcza nieskazitelną kulę draenetystu, która unosi się przed nim w powietrzu.', '', 0),
(3473, 'koKR', 'To fascynujące... Słyszałem, jak orkowie twierdzą, że ludzie cuchną obrzydliwie, i słyszałem, jak ludzie twierdzą, że orkowie cuchną paskudnie; a dla mnie wszystkie rasy tych ziem wydzielają tę samą woń: plugawy, przyprawiający o zawrót głowy zapach chciwości.$B$BWątpisz w słuszność moich słów? Czy nie widzisz, że rzeczy, które rządzą twoim życiem, to jedynie wyciek z chciwości dyktującej każdą twoją decyzję?$B$BNiech tak będzie. Skoro to chciwość wygnała mnie z domu, to chciwość sprawi, że do niego wrócę.', '', 0),
(3474, 'koKR', 'A więc $gwróciłeś:wróciłaś;, by pomóc Kum\'ishy, $r? Nie martw się, to ukłucie, które czujesz w dołku, to tylko upadek twojej siły woli.$B$BNa szczęście do tej zbiórki siła woli nie będzie ci potrzebna. Jestem pewien, że spodobają ci się błyskotki, które będą na ciebie czekać, gdy wrócisz z przedmiotem.\n', '', 0),
(3475, 'koKR', 'Udało się, szczelina jest otwarta!! Bracia moi, powstańcie i wracajcie do domu! Rubież czeka!', '', 0),
(3476, 'koKR', 'Pospieszcie się, bracia! Musicie iść natychmiast! Nie wiem, jak długo szczelina pozostanie otwarta!', '', 0),
(3477, 'koKR', 'I teraz już wiesz, dlaczego mieszkam w kraterze.', '', 0),
(3521, 'koKR', 'Bestie tych jałowych ziem wykazują nadnaturalne cechy, dotąd niespotykane w przyrodzie.$B$BWysunęliśmy teorię, że energia uwolniona przy otwarciu Mrocznego Portalu przeniknęła do ich ciał i zmusiła te stworzenia do wyewoluowania w obecne formy.$B$BTo bez wątpienia groźne bestie, ale sądzimy też, że mogą okazać się bardzo przydatne w naszych badaniach.$B$BMoże $gzechciałbyś:zechciałabyś; pomóc nam w badaniu tych bestii, $n?\n', '', 0),
(3561, 'koKR', '', 'Podczas gdy mój brat Drazial skupia się w swoich analizach na fizycznej naturze bestii z jałowych ziem, ja zajmuję się raczej umysłowymi i duchowymi aspektami tutejszej fauny.$B$BTo prawda, że te bestie wykazują niezwykłą siłę, zwinność i wytrzymałość, ale niektóre z nich mają też wielką inteligencję i zdolności regeneracji niezwiązane z ich fizycznością.$B$BMoże $gzechciałbyś:zechciałabyś; pomóc w rozwoju moich badań, $r?\n', 0),
(4591, 'koKR', 'Jestem na wieki związany z tym przeklętym światem. Czego pragniesz, $gśmiertelniku:śmiertelniczko;?', '', 0),
(4592, 'koKR', 'Chcę stanąć do walki z Plugawicielem.', 'Chcę stanąć do walki z Plugawicielem.', 0),
(9607, 'koKR', 'Z pewnością jesteś daleko od domu, $r.', '', 0),
(13393, 'koKR', 'Niedawno w tym miejscu rozegrała się straszliwa bitwa. My ze Strażnicy Otchłani wraz z Argentowym Brzaskiem powstrzymywaliśmy falę demonów, które nieustannie wylewały się z Mrocznego Portalu.$B$BTo były mroczne dni, pełne rozlewu krwi i rozpaczy...$B$BAle wkrótce dołączyły do nas Królestwa Azeroth i odepchnęły potwory! Walki trwają dalej po drugiej stronie Portalu...$B$BW tym obozie panuje teraz spokój, ale obawiam się, że tutejsza cisza skrywa szaleństwo czające się za tą piekielną bramą.', '', 0),
(17626, 'koKR', 'Ziemia w tym miejscu jest jeszcze ciepła od świeżo przelanej krwi. Ach, oddałbym własne oko, by być tutaj, gdy demony przedarły się przez ten portal i starły się z bohaterami Azeroth! Cóż to była za bitwa!$B$BAle teraz po drugiej stronie toczą się jeszcze zacieklejsze walki!', '', 0),
(17808, 'koKR', 'Throm\'ka, $gbracie:siostro;! Witaj w Rubieży. Horda potrzebuje całej siły, jaką zdoła zebrać w tym roztrzaskanym świecie. Obiecuję ci: jeśli $gprzyszedłeś:przyszłaś; tu szukać chwalebnej walki, najesz się jej do syta.', '', 0);
